// Die Instanzwerte kommen aus sub-einstellungen (Knoten davor) und werden
// in der Data Table pw_config gepflegt (n8n-Oberfläche, "Data Tables").
// HIER stehen nur die FACHLICHEN Einstellungen dieses Workflows: Fristen,
// Tag-Namen, Feldnamen.
const werte = $('Einstellungen holen').first().json;
const pw = (key) => {
  const v = werte[key];
  if (v === undefined || String(v).trim() === '') {
    throw new Error('pw_config: "' + key + '" fehlt oder ist leer; in der n8n-Oberfläche unter "Data Tables" eintragen.');
  }
  return v;
};
return [{
  json: {
    // ── aus der Data Table pw_config ──
    // Dieser Workflow verschickt keine Mail und braucht deshalb nur die
    // Paperless-Adresse für seine API-Aufrufe.
    paperless_url: pw('paperless_url')
  }
}];

// Dokument-ID aus dem Paperless-Webhook holen.
// Body kann { doc_id }, { id } oder { doc_url } enthalten.
const body = $('Webhook').first().json.body ?? {};
let id = body.doc_id ?? body.id;
if (!id && body.doc_url) {
  id = String(body.doc_url).match(/\/documents\/(\d+)/)?.[1];
}
if (!id) throw new Error('Keine doc_id/doc_url im Webhook-Body');
return [{ json: { id: Number(id) } }];

const doc = $input.first().json;
const content = (doc.content ?? '').trim();
if (!content) throw new Error('Dokument hat keinen Text (content leer)');
return [{ json: { id: doc.id, content, docTags: doc.tags ?? [] } }];

// ============================================================
// KONFIGURATION
const OBJEKT_PREFIX = 'obj:';
const MISTRAL_MODEL = 'mistral-small-latest';
const MAX_CONTENT_CHARS = 8000;
// ============================================================

const src = $('Extract content').first().json;
const alle = $input.first().json.results || [];
const objekte = alle.filter(t => String(t.name || '').toLowerCase().startsWith(OBJEKT_PREFIX));
if (!objekte.length) {
  throw new Error('Keine Objekt-Tags mit Präfix "' + OBJEKT_PREFIX + '" in Paperless gefunden; pro Liegenschaft einen Tag wie "obj:Musterstr-12" anlegen.');
}

// Manuelle Zuordnung nie überschreiben: hat das Dokument schon einen obj:-Tag, überspringen.
const bereits = objekte.find(t => (src.docTags || []).includes(t.id));

const liste = objekte.map(t => t.id + ' = ' + t.name).join('\n');

const SYSTEM_PROMPT = `Du bist ein Klassifikationssystem einer Hausverwaltung. Du bekommst den OCR-Volltext eines Dokuments und ordnest es genau einer Liegenschaft (Objekt) zu.

Verfügbare Objekte (id = Bezeichnung):
${liste}

Regeln:
- Wähle genau ein Objekt, nur wenn es eindeutig im Dokument erkennbar ist (Objektadresse, Objektbezeichnung, Wohnungs-/Einheitsnummer)
- Die Adresse des Absenders oder der Hausverwaltung selbst zählt NICHT als Objektadresse
- Verwende keine Vermutungen; passt kein Objekt eindeutig, gib null zurück
- Antworte ausschließlich mit gültigem JSON in genau diesem Format und ohne weitere Felder:
{"objekt_tag_id": 12} oder {"objekt_tag_id": null}`;

const userContent = `OCR-Volltext (Auszug, ggf. gekürzt):\n---\n${src.content.slice(0, MAX_CONTENT_CHARS)}\n---\n\nOrdne nun das Objekt zu und antworte als JSON.`;

return [{
  json: {
    id: src.id,
    bereits_zugeordnet: !!bereits,
    allowed_ids: objekte.map(t => t.id),
    mistralBody: {
      model: MISTRAL_MODEL,
      response_format: { type: 'json_object' },
      temperature: 0,
      max_tokens: 100,
      messages: [
        { role: 'system', content: SYSTEM_PROMPT },
        { role: 'user', content: userContent },
      ],
    },
  },
}];

// Mistral-Antwort parsen. Sicherheitsnetz: nur Tag-IDs aus der
// Objektliste akzeptieren; das LLM darf nichts erfinden.
const src = $('Prompt bauen').first().json;
const aiItem = $input.first().json;

let raw = aiItem?.choices?.[0]?.message?.content;
if (typeof raw !== 'string' || raw.trim() === '') {
  throw new Error('Keine Antwort von Mistral erhalten: ' + JSON.stringify(aiItem).slice(0, 500));
}
raw = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
let parsed;
try {
  parsed = JSON.parse(raw);
} catch {
  throw new Error('Mistral-Antwort ist kein gültiges JSON: ' + raw.slice(0, 500));
}

let tagId = parsed.objekt_tag_id;
if (typeof tagId === 'string' && /^\d+$/.test(tagId)) tagId = Number(tagId);
if (!src.allowed_ids.includes(tagId)) tagId = null;

return [{ json: { id: src.id, objekt_tag_id: tagId, gefunden: tagId !== null } }];
